// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadRobotoMono = makeLoadFont('RobotoMono');
const loadInter = makeLoadFont('Inter');

// Module-level font loading
const { fontFamily: robotoMonoFamily } = loadRobotoMono();
const { fontFamily: interFamily } = loadInter();



export type TimerProps = Record<string, any>;

const Timer: React.FC<TimerProps> = ({
  backgroundColor = "#0f172a",
  transparentBackground = false,
  delayBeforeStartInSeconds = 5,
  durationInSeconds = 50,
  holdDurationInSeconds = 3,
  timerLabel = "TIME REMAINING",
  labelColor = "#94a3b8",
  timerColor = "#38bdf8",
  boxBackgroundColor = "#020617",
  boxBorderColor = "#38bdf8",
  showDecimals = true,
  pulseOnZero = true,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timer Calculations
  const delayFrames = delayBeforeStartInSeconds * fps;
  const countdownFrames = durationInSeconds * fps;
  
  // Calculate remaining time, factoring in the start delay
  const activeFrame = Math.max(0, frame - delayFrames);
  const remainingSeconds = Math.max(0, durationInSeconds - activeFrame / fps);
  
  // Formatter logic for digital MM:SS format
  const totalSecsCeil = Math.ceil(remainingSeconds);
  const displayMins = Math.floor(totalSecsCeil / 60);
  const displaySecs = totalSecsCeil % 60;

  const displayMinsDec = Math.floor(remainingSeconds / 60);
  const displaySecsDec = Math.floor(remainingSeconds % 60);
  const displayMs = Math.floor((remainingSeconds % 1) * 10);

  const displayValue = showDecimals 
    ? `${displayMinsDec.toString().padStart(2, "0")}:${displaySecsDec.toString().padStart(2, "0")}.${displayMs}`
    : `${displayMins.toString().padStart(2, "0")}:${displaySecs.toString().padStart(2, "0")}`;

  // Entrance Animations (happens immediately, before delay finishes)
  const containerOpacity = interpolate(frame, [0, 15], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  const containerScale = spring({
    fps,
    frame,
    config: { damping: 14, stiffness: 100 },
  });

  // End State (Zero) Pulse Animation
  const isZero = remainingSeconds === 0;
  let pulseScale = 1;
  let pulseOpacity = 1;

  if (isZero && pulseOnZero) {
    // Frames elapsed since hitting zero
    const framesSinceZero = activeFrame - countdownFrames;
    // Creates a looping subtle pulse every second
    const pulseProgress = Math.max(0, framesSinceZero % fps) / fps;
    
    pulseScale = interpolate(pulseProgress, [0, 0.5, 1], [1, 1.05, 1], {
      extrapolateRight: "clamp",
      extrapolateLeft: "clamp",
    });
    pulseOpacity = interpolate(pulseProgress, [0, 0.5, 1], [1, 0.8, 1], {
      extrapolateRight: "clamp",
      extrapolateLeft: "clamp",
    });
  }

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        transition: "none",
      }}
    >
      <div
        style={{
          backgroundColor: boxBackgroundColor,
          border: `16px solid ${boxBorderColor}`,
          borderRadius: 24,
          padding: `${height * 0.08}px ${height * 0.12}px`,
          boxShadow: `0 0 40px ${boxBorderColor}40, inset 0 0 40px ${boxBorderColor}20`,
          position: "relative",
          opacity: containerOpacity,
          transform: `scale(${containerScale})`,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          transition: "none",
          overflow: "hidden", // Clips scanlines and glare to border radius
        }}
      >
        {/* Screen Glare / Reflection */}
        <div style={{
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          height: "50%",
          background: "linear-gradient(to bottom, rgba(255,255,255,0.05), rgba(255,255,255,0))",
          pointerEvents: "none",
          zIndex: 0,
        }} />

        {/* Scanlines Overlay */}
        <div style={{
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          background: "linear-gradient(to bottom, rgba(0,0,0,0) 50%, rgba(0,0,0,0.2) 50%)",
          backgroundSize: "100% 8px",
          pointerEvents: "none",
          zIndex: 2,
        }} />

        {/* Inner Content Box */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            justifyContent: "center",
            transform: `scale(${pulseScale})`,
            opacity: pulseOpacity,
            transition: "none",
            zIndex: 1, // Sit below scanlines but above screen glare
            textAlign: "center",
          }}
        >
          {timerLabel && (
            <div
              style={{
                fontFamily: interFamily,
                color: labelColor,
                fontSize: height * 0.035,
                fontWeight: 600,
                textTransform: "uppercase",
                letterSpacing: "0.2em",
                marginBottom: height * 0.02,
                transition: "none",
              }}
            >
              {timerLabel}
            </div>
          )}
          
          <div style={{ position: "relative", display: "flex", transition: "none" }}>
            {/* Active Numerals */}
            <div
              style={{
                fontFamily: robotoMonoFamily,
                color: timerColor,
                fontSize: height * 0.22,
                fontWeight: 700,
                lineHeight: 1,
                fontVariantNumeric: "tabular-nums",
                textShadow: `0 0 15px ${timerColor}80`,
                transition: "none",
              }}
            >
              {displayValue}
            </div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default Timer;